<template>
  <div class="page-container dolphin-page">
    <div class="page-header"><div class="page-header-title"><h1>DolphinScheduler 执行总览</h1><p>按项目查看工作流与任务节点执行情况，定时检查独立运行并按告警规则通知。</p></div><div class="page-actions"><button class="btn btn-ghost" @click="edit()">新增连接</button><button class="btn btn-primary" :disabled="!selected || loading" @click="edit(selected)">连接与告警配置</button></div></div>
    <p v-if="error" class="inline-error" role="alert">{{ error }}</p>
    <section class="card"><form class="query-grid" @submit.prevent="loadOverview"><label class="filter-label">监控连接<select v-model="connectionId" class="form-control" @change="changeConnection"><option v-if="!connections.length" value="">请先配置连接</option><option v-for="c in connections" :key="c.id" :value="String(c.id)">{{ c.service_name }}{{ c.enabled ? '' : '（定时检查停用）' }}</option></select></label><label class="filter-label">项目<select v-model="project" class="form-control"><option value="">配置范围内全部项目</option><option v-for="p in scopeProjects" :key="p.code" :value="p.code">{{ p.description || p.name }} · {{ p.code }}</option></select></label><label class="filter-label">开始时间<input v-model="start" type="datetime-local" step="1" class="form-control"></label><label class="filter-label">结束时间<input v-model="end" type="datetime-local" step="1" class="form-control"></label><div class="page-actions"><button class="btn btn-primary" :disabled="!selected || loading">{{ loading ? '正在查询…' : '查询 / 刷新' }}</button><button type="button" class="btn btn-ghost" :disabled="loading" @click="start = ''; end = ''; project = ''; loadOverview()">滚动监控窗口</button></div></form><p class="form-hint">日期留空时使用连接配置的滚动窗口。自选日期只影响本页查询，不改变定时告警。查询最多 31 天、每个项目最多 10000 条，超限会明确报错。</p><p v-if="selected" class="form-hint">定时检查：{{ selected.enabled ? '启用' : '停用' }} · 最近状态 {{ selected.last_status || '尚未检查' }} · {{ selected.last_checked_at || '暂无时间' }} <router-link :to="'/alerts/tasks?service_id=' + selected.id">查看发送任务与重试</router-link></p></section>
    <section v-if="!connections.length && !loading" class="card empty-state">尚未配置 DolphinScheduler 连接。新增连接后即可读取项目和执行记录。</section>
    <template v-if="snapshot">
      <div class="summary-grid"><div v-for="(label,key) in summaryLabels" :key="key" class="card summary-item"><span>{{ label }}</span><strong :class="key">{{ snapshot[key] }}</strong></div></div>
      <p class="text-muted snapshot-time">查询范围：{{ snapshot.start }} 至 {{ snapshot.end }} · 采集于 {{ snapshot.collected_at }}。无执行记录表示该时间段无实例，不代表调度一定正常。</p>
      <section class="card"><div class="card-header"><h2 class="card-title">项目执行概况</h2><input v-model="projectSearch" class="form-control compact-search" placeholder="搜索项目名称 / 说明 / 编码"></div><div class="table-wrap"><table class="table"><thead><tr><th>项目 / 说明</th><th>项目编码</th><th>实例总数</th><th>成功</th><th>运行 / 等待</th><th>异常命中</th><th>操作</th></tr></thead><tbody><tr v-for="p in projectPager.items" :key="p.code"><td>{{ p.description || p.name }}<small class="text-muted">{{ p.name }}</small></td><td>{{ p.code }}</td><td>{{ p.total }}</td><td>{{ p.success }}</td><td>{{ p.running }}</td><td><span :class="['badge',p.abnormal ? 'badge-down' : 'badge-up']">{{ p.abnormal }}</span></td><td><button class="btn btn-ghost btn-sm" @click="instanceProject = p.code">查看实例</button></td></tr><tr v-if="!projectPager.total"><td colspan="7" class="empty-state">暂无符合条件的项目</td></tr></tbody></table></div><PaginationControls v-model:page="projectPager.page" v-model:page-size="projectPager.pageSize" :total="projectPager.total" label="DolphinScheduler 项目" /></section>
      <section class="card"><div class="card-header"><div><h2 class="card-title">工作流实例</h2><p class="form-hint">异常命中包含配置的失败状态及运行超时，与“成功 / 运行 / 其他”分类可能重叠。</p></div><div class="toolbar"><select v-model="instanceProject" class="form-control" aria-label="筛选实例项目"><option value="">全部查询项目</option><option v-for="p in snapshot.projects" :key="p.code" :value="p.code">{{ p.description || p.name }}</option></select><select v-model="state" class="form-control" aria-label="筛选执行状态"><option value="">全部状态</option><option value="abnormal">仅异常命中</option><option v-for="s in stateOptions" :key="s" :value="s">{{ stateLabel(s) }}</option></select><input v-model="search" class="form-control" placeholder="搜索实例名称 / ID"></div></div><div class="table-wrap"><table class="table"><thead><tr><th>项目</th><th>实例 / ID</th><th>状态</th><th>开始时间</th><th>结束时间</th><th>耗时</th><th>操作</th></tr></thead><tbody><tr v-for="row in instancePager.items" :key="row.project_code + ':' + row.id"><td>{{ row.project_description || row.project_name }}</td><td class="instance-name">{{ row.name }}<small class="text-muted">{{ row.id }}</small></td><td><span :class="['badge',row.abnormal ? 'badge-down' : row.state === 'SUCCESS' ? 'badge-up' : 'badge-info']">{{ stateLabel(row.state) }}</span></td><td>{{ row.start_time || '—' }}</td><td>{{ row.end_time || '—' }}</td><td>{{ row.duration || '—' }}</td><td><button class="btn btn-ghost btn-sm" @click="showTasks(row)">任务节点</button></td></tr><tr v-if="!instancePager.total"><td colspan="7" class="empty-state">暂无符合条件的工作流实例</td></tr></tbody></table></div><PaginationControls v-model:page="instancePager.page" v-model:page-size="instancePager.pageSize" :total="instancePager.total" label="工作流实例" /></section>
    </template>
    <section v-if="editing" ref="editor" class="card"><div class="card-header"><h2 class="card-title">{{ form.id ? '编辑连接与告警规则' : '新增 DolphinScheduler 连接' }}</h2><button class="btn btn-ghost btn-sm" @click="editing = false">关闭配置</button></div><form @submit.prevent="save"><div class="form-row"><label class="form-group">连接名称<input v-model="form.service_name" required maxlength="120" class="form-control"></label><label class="form-group">接口根地址<input v-model="form.config.base_url" type="url" required class="form-control" placeholder="http://scheduler:12345/dolphinscheduler"></label><label class="form-group">Token<input v-model="token" type="password" autocomplete="new-password" :required="!form.id" class="form-control" placeholder="编辑时留空保留原 Token"></label></div><div class="form-row"><label class="form-group">项目编码（逗号分隔，留空监控全部可访问项目）<input v-model="form.config.project_codes" class="form-control" placeholder="6819918706304"></label><label class="form-group">滚动检查窗口（小时）<input v-model.number="form.config.window_hours" required type="number" min="1" max="744" class="form-control"></label><label class="form-group">检查间隔（秒）<input v-model.number="form.check_interval" required type="number" min="30" max="86400" class="form-control"></label></div><div class="form-row"><label class="form-group">异常状态（逗号分隔）<input v-model="form.config.alert_states" required class="form-control"><span class="form-hint">支持 FAILURE、STOP、KILL、PAUSE、NEED_FAULT_TOLERANCE</span></label><label class="form-group">运行超时（分钟，0 关闭）<input v-model.number="form.config.running_timeout_minutes" required type="number" min="0" max="10080" class="form-control"></label></div><label class="check-label"><input v-model="form.config.alert_on_empty" type="checkbox">窗口内无实例时视为检查异常（UNKNOWN）</label><ServiceAlertFields :form="form" :groups="groups" /><p class="form-hint">异常按连接汇总告警；同一异常持续存在时按提醒间隔再次通知，恢复后发送恢复通知。接口鉴权或采集失败使用 UNKNOWN 规则。Token 加密保存，不回显。</p><p v-if="saveError" role="alert" class="inline-error">{{ saveError }}</p><div class="page-actions"><button class="btn btn-primary" :disabled="saving">{{ saving ? '正在保存…' : '保存连接与规则' }}</button><button type="button" class="btn btn-ghost" @click="editing = false">取消</button></div></form></section>
    <DetailDrawer :open="!!taskInstance" title="工作流任务节点" @close="taskInstance = null"><template v-if="taskInstance"><h3>{{ taskInstance.name }}</h3><p v-if="taskError" role="alert">{{ taskError }}</p><p v-if="taskLoading">正在读取任务节点…</p><div class="table-wrap"><table class="table"><thead><tr><th>任务</th><th>类型</th><th>状态</th><th>开始 / 结束</th></tr></thead><tbody><tr v-for="task in taskPager.items" :key="task.id"><td>{{ task.name }}<small>{{ task.id }}</small></td><td>{{ task.task_type }}</td><td>{{ stateLabel(task.state) }}</td><td>{{ task.start_time }}<br>{{ task.end_time }}</td></tr></tbody></table></div><p v-if="!taskLoading && !tasks.length && !taskError">该实例暂无任务节点。</p><PaginationControls v-model:page="taskPager.page" v-model:page-size="taskPager.pageSize" :total="taskPager.total" label="任务节点" /></template></DetailDrawer>
  </div>
</template>
<script setup>
import { ref, computed, onMounted, nextTick } from 'vue'
import { useRoute } from 'vue-router'
import { api } from '../api'
import { usePagination } from '../composables/usePagination'
import PaginationControls from '../components/PaginationControls.vue'
import ServiceAlertFields from '../components/ServiceAlertFields.vue'
import DetailDrawer from '../components/DetailDrawer.vue'
const route=useRoute(),connections=ref([]),connectionId=ref(''),groups=ref([]),projects=ref([]),snapshot=ref(null),loading=ref(false),error=ref(''),project=ref(''),start=ref(''),end=ref(''),projectSearch=ref(''),search=ref(''),state=ref(''),instanceProject=ref('')
const selected=computed(()=>connections.value.find(c=>String(c.id)===connectionId.value)),configOf=c=>{try{return JSON.parse(c.config_json || '{}')}catch{return {}}}
const scopeProjects=computed(()=>{const codes=String(configOf(selected.value || {}).project_codes || '').split(',').map(x=>x.trim()).filter(Boolean);return projects.value.filter(p=>!codes.length || codes.includes(String(p.code)))})
const summaryLabels={total:'工作流实例',success:'执行成功',running:'运行 / 等待',abnormal:'异常命中',other:'其他状态'}
const stateNames={SUCCESS:'成功',FORCED_SUCCESS:'强制成功',FAILURE:'失败',STOP:'已停止',KILL:'已终止',PAUSE:'已暂停',RUNNING_EXECUTION:'运行中',SUBMITTED_SUCCESS:'已提交',DELAY_EXECUTION:'延迟执行',SERIAL_WAIT:'串行等待',READY_PAUSE:'准备暂停',READY_STOP:'准备停止',NEED_FAULT_TOLERANCE:'待容错'}
const stateLabel=s=>stateNames[s] || s || '未知',stateOptions=computed(()=>[...new Set((snapshot.value?.instances || []).map(x=>x.state))])
const projectPager=usePagination(()=> (snapshot.value?.projects || []).filter(p=>(p.name+' '+p.description+' '+p.code).toLowerCase().includes(projectSearch.value.toLowerCase())),[projectSearch,snapshot])
const instancePager=usePagination(()=> (snapshot.value?.instances || []).filter(r=>(!instanceProject.value || r.project_code===instanceProject.value)&&(!state.value || (state.value==='abnormal'?r.abnormal:r.state===state.value))&&(r.name+' '+r.id).toLowerCase().includes(search.value.toLowerCase())),[search,state,instanceProject,snapshot])
let generation=0
async function loadOverview(){if(!selected.value)return;const n=++generation;loading.value=true;error.value='';snapshot.value=null;instanceProject.value='';try{const result=await api.dolphinOverview(connectionId.value,{start:start.value,end:end.value,project:project.value});if(n===generation)snapshot.value=result}catch(e){if(n===generation)error.value=e.message}finally{if(n===generation)loading.value=false}}
async function changeConnection(){++generation;snapshot.value=null;project.value='';projects.value=[];error.value='';const id=connectionId.value;try{const rows=await api.dolphinProjects(id);if(id!==connectionId.value)return;projects.value=rows;await loadOverview()}catch(e){if(id===connectionId.value){error.value=e.message;loading.value=false}}}
const editing=ref(false),editor=ref(null),token=ref(''),saving=ref(false),saveError=ref(''),form=ref({})
async function edit(c){form.value=c?{...c,config:configOf(c),alert_group_ids:[...(c.alert_group_ids || [])]}:{service_name:'DolphinScheduler',service_type:'dolphinscheduler',enabled:true,service_alert_enabled:true,check_interval:60,service_consecutive_failures:1,service_recover_successes:1,unknown_alert_enabled:true,unknown_consecutive_failures:1,alert_repeat_interval_seconds:300,alert_group_ids:[],config:{base_url:'',project_codes:'',window_hours:24,alert_states:'FAILURE,STOP,KILL',running_timeout_minutes:180,alert_on_empty:false}};token.value='';saveError.value='';editing.value=true;await nextTick();editor.value?.scrollIntoView({block:'start',behavior:'smooth'})}
async function save(){saving.value=true;saveError.value='';try{const data={...form.value,service_type:'dolphinscheduler',check_interval_unit:'seconds',check_interval_value:form.value.check_interval};delete data.check_timeout_seconds;delete data.secret_config_json;if(token.value.trim())data.secret_config={token:token.value.trim()};const result=await api.saveDolphinConnection(form.value.id,data);connections.value=await api.dolphinConnections();connectionId.value=String(result.id);token.value='';editing.value=false;await changeConnection()}catch(e){saveError.value=e.message}finally{saving.value=false}}
const tasks=ref([]),taskInstance=ref(null),taskLoading=ref(false),taskError=ref(''),taskPager=usePagination(tasks,[taskInstance])
async function showTasks(row){taskInstance.value=row;tasks.value=[];taskError.value='';taskLoading.value=true;try{const rows=await api.dolphinTasks(connectionId.value,row.project_code,row.id);if(taskInstance.value===row)tasks.value=rows}catch(e){if(taskInstance.value===row)taskError.value=e.message}finally{if(taskInstance.value===row)taskLoading.value=false}}
onMounted(async()=>{try{[connections.value,groups.value]=await Promise.all([api.dolphinConnections(),api.listAlertGroups()]);connectionId.value=String(connections.value.find(c=>String(c.id)===String(route.query.edit))?.id || connections.value[0]?.id || '');if(route.query.edit && selected.value)await edit(selected.value);if(connectionId.value)await changeConnection();else await edit()}catch(e){error.value=e.message}})
</script>
<style scoped>
.query-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; }
.summary-grid { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:16px; margin-bottom:16px; }
.summary-item { margin-bottom:0; }.summary-item span { color:var(--text-muted);font-size:13px; }.summary-item strong { display:block;font-size:28px;margin-top:8px; }.success {color:#16a34a}.abnormal {color:#dc2626}.running {color:#0284c7}
.snapshot-time {font-size:12px;margin-bottom:20px}.compact-search {max-width:300px}.instance-name {max-width:360px;overflow-wrap:anywhere}small {display:block;margin-top:4px}.check-label {display:flex;align-items:center;gap:8px;margin-bottom:20px;font-size:13px}.dolphin-page .form-group {display:flex;flex-direction:column;gap:8px;font-size:13px}.dolphin-page .toolbar {flex-wrap:wrap}.dolphin-page .toolbar .form-control {width:180px;max-width:100%}
@media(max-width:800px){.summary-grid {grid-template-columns:repeat(2,minmax(0,1fr))}.query-grid {grid-template-columns:minmax(0,1fr)}}
</style>
